-- FORGE v2: exercise library, reusable routines, weekly plan and workout history.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,created_at timestamptz not null default now());
create table if not exists public.exercises(id uuid primary key default gen_random_uuid(),name text not null unique,muscle_group text not null,equipment text,instructions text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.workouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Entrenamiento',performed_at timestamptz not null default now(),duration_minutes integer check(duration_minutes is null or duration_minutes>=0),notes text,template_id uuid,created_at timestamptz not null default now());
create table if not exists public.workout_sets(id uuid primary key default gen_random_uuid(),workout_id uuid not null references public.workouts(id) on delete cascade,exercise_id uuid not null references public.exercises(id),set_number integer not null check(set_number>0),reps integer not null check(reps>0),weight_kg numeric(7,2) not null default 0 check(weight_kg>=0),rest_seconds integer check(rest_seconds is null or rest_seconds>=0),rpe numeric(3,1) check(rpe is null or(rpe>=0 and rpe<=10)),notes text,created_at timestamptz not null default now(),unique(workout_id,exercise_id,set_number));
create table if not exists public.training_templates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null, is_favorite boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.training_template_exercises(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.training_templates(id) on delete cascade,exercise_id uuid not null references public.exercises(id),position integer not null default 0,created_at timestamptz not null default now(),unique(template_id,exercise_id));
create table if not exists public.training_schedule(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,weekday smallint not null check(weekday between 0 and 6),template_id uuid references public.training_templates(id) on delete set null,unique(user_id,weekday));
alter table public.workouts add column if not exists template_id uuid references public.training_templates(id) on delete set null;
create index if not exists workouts_user_date_idx on public.workouts(user_id,performed_at desc);
create index if not exists workout_sets_workout_idx on public.workout_sets(workout_id);
create index if not exists workout_sets_exercise_idx on public.workout_sets(exercise_id);
create index if not exists templates_user_idx on public.training_templates(user_id);
create index if not exists template_exercises_order_idx on public.training_template_exercises(template_id,position);
alter table public.profiles enable row level security;alter table public.exercises enable row level security;alter table public.workouts enable row level security;alter table public.workout_sets enable row level security;alter table public.training_templates enable row level security;alter table public.training_template_exercises enable row level security;alter table public.training_schedule enable row level security;
drop policy if exists "profile read own" on public.profiles;create policy "profile read own" on public.profiles for select to authenticated using(auth.uid()=id);
drop policy if exists "profile update own" on public.profiles;create policy "profile update own" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "profile insert own" on public.profiles;create policy "profile insert own" on public.profiles for insert to authenticated with check(auth.uid()=id);
drop policy if exists "authenticated read active exercises" on public.exercises;create policy "authenticated read active exercises" on public.exercises for select to authenticated using(is_active=true);
drop policy if exists "own workouts only" on public.workouts;create policy "own workouts only" on public.workouts for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own workout sets only" on public.workout_sets;create policy "own workout sets only" on public.workout_sets for all to authenticated using(exists(select 1 from public.workouts w where w.id=workout_id and w.user_id=auth.uid())) with check(exists(select 1 from public.workouts w where w.id=workout_id and w.user_id=auth.uid()));
drop policy if exists "own templates" on public.training_templates;create policy "own templates" on public.training_templates for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own template exercises" on public.training_template_exercises;create policy "own template exercises" on public.training_template_exercises for all to authenticated using(exists(select 1 from public.training_templates t where t.id=template_id and t.user_id=auth.uid())) with check(exists(select 1 from public.training_templates t where t.id=template_id and t.user_id=auth.uid()));
drop policy if exists "own weekly schedule" on public.training_schedule;create policy "own weekly schedule" on public.training_schedule for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);

-- API privileges: RLS still restricts rows to each authenticated user.
grant usage on schema public to authenticated;
grant select on public.exercises to authenticated;
grant select, insert, update, delete on public.profiles to authenticated;
grant select, insert, update, delete on public.workouts to authenticated;
grant select, insert, update, delete on public.workout_sets to authenticated;
grant select, insert, update, delete on public.training_templates to authenticated;
grant select, insert, update, delete on public.training_template_exercises to authenticated;
grant select, insert, update, delete on public.training_schedule to authenticated;

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.exercises(name,muscle_group,equipment,instructions) values
('Press banca','Pecho','Barra','Túmbate en el banco, retrae las escápulas y apoya los pies. Baja la barra controladamente hasta el pecho y empuja hasta extender los brazos sin perder la estabilidad.'),('Press inclinado con mancuernas','Pecho','Mancuernas','Ajusta el banco a unos 30 grados. Baja las mancuernas a los lados del pecho y empuja hacia arriba manteniendo las muñecas alineadas.'),('Aperturas en polea','Pecho','Polea','Con una ligera flexión de codos, junta las manos delante del pecho y vuelve lentamente hasta notar el estiramiento.'),('Jalón al pecho','Espalda','Polea','Sujeta la barra algo más abierta que los hombros. Lleva los codos hacia abajo y acerca la barra a la parte alta del pecho sin balancearte.'),('Remo con barra','Espalda','Barra','Inclina el torso con espalda neutra. Lleva la barra hacia el abdomen y baja controladamente.'),('Remo sentado','Espalda','Polea','Mantén el torso estable, tira del agarre hacia el abdomen y junta las escápulas sin encoger los hombros.'),('Sentadilla','Piernas','Barra','Coloca la barra estable, flexiona cadera y rodillas manteniendo el tronco firme. Desciende hasta tu rango cómodo y empuja el suelo para subir.'),('Peso muerto rumano','Piernas','Barra','Desplaza la cadera hacia atrás con rodillas ligeramente flexionadas. Baja la barra cerca de las piernas manteniendo la espalda neutra y vuelve extendiendo la cadera.'),('Prensa de piernas','Piernas','Máquina','Apoya la espalda, coloca los pies a una anchura cómoda. Baja la plataforma controladamente y empuja sin bloquear las rodillas.'),('Press militar','Hombros','Mancuernas','Desde los hombros, empuja las mancuernas por encima de la cabeza manteniendo abdomen firme y evitando arquear la zona lumbar.'),('Elevaciones laterales','Hombros','Mancuernas','Eleva los brazos hacia los lados con codos ligeramente flexionados hasta la altura de los hombros, sin impulso.'),('Pájaros','Hombros','Mancuernas','Inclina el torso y abre los brazos hacia los lados controlando el movimiento para trabajar la parte posterior del hombro.'),('Curl de bíceps','Bíceps','Mancuernas','Con los codos pegados al cuerpo, flexiona los brazos sin balancear el tronco y baja lentamente.'),('Curl martillo','Bíceps','Mancuernas','Sujeta las mancuernas con agarre neutro y flexiona los codos manteniendo las muñecas alineadas.'),('Extensión tríceps polea','Tríceps','Polea','Con los codos junto al cuerpo, extiende los antebrazos hacia abajo y vuelve lentamente.'),('Fondos','Tríceps','Peso corporal','Estabiliza los hombros, flexiona los codos para descender dentro de un rango cómodo y empuja para subir.'),('Plancha','Core','Peso corporal','Apoya antebrazos y puntas de los pies. Mantén el cuerpo alineado y el abdomen contraído.'),('Crunch abdominal','Core','Peso corporal','Eleva ligeramente los hombros acercando las costillas a la pelvis, sin tirar del cuello.') on conflict(name) do update set instructions=excluded.instructions,muscle_group=excluded.muscle_group,equipment=excluded.equipment;
